/* GoalOS — static local-first app. Google Drive sync is strictly opt-in. */
(() => {
'use strict';
const KEY='goalos.v1.userdata'; const THEME='goalos.theme';
const PAGES={overview:'Overview',transactions:'Transactions',tasks:'Goal tracker',loans:'Loans',analytics:'Analytics',workbook:'Workbook explorer',settings:'Settings & backup'};
const el=id=>document.getElementById(id);const app=el('app');
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(id)=>`<svg aria-hidden="true"><use href="#i-${id}"></use></svg>`;
const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const fmtDate=v=>{if(!v)return 'No date';let d=new Date(`${String(v).slice(0,10)}T12:00:00`);return Number.isNaN(d.getTime())?String(v):d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});};
const n=v=>Number(v)||0;
const state={page:'overview',filters:{type:'All',status:'All',priority:'All',taskSort:'due',account:'All',period:'All'},search:'',sheet:0,loaded:false,data:null};
function money(value,compact=false){const currency=state.data?.settings?.currency||'PKR';let v=n(value);if(compact && Math.abs(v)>=100000)return `${currency} ${(v/100000).toFixed(2)}L`;return `${currency} ${new Intl.NumberFormat('en-PK',{maximumFractionDigits:2}).format(v)}`;}
function blank(){return {version:1,meta:{sourceFile:'New workspace',importedAt:today()},settings:{year:2026,currency:'PKR',openingBalance:0,savingsTarget:20000,reminders:{enabled:true,daysBefore:[7,3,1,0]},categories:['Food','Transport','Rent','Bills','Shopping','Health','Education','Entertainment','Business','Salary','Investment','Loan','Saving','Other'],accounts:['Cash','Mobile Wallet','Bank Account','Saving Account']},transactions:[],tasks:[],loans:[],sheets:[]};}
function validateData(d){if(!d||typeof d!=='object'||!Array.isArray(d.transactions)||!Array.isArray(d.tasks)||!Array.isArray(d.loans))throw Error('Invalid GoalOS backup. Expected transactions, tasks and loans.');let defaults=blank();return {...defaults,...d,settings:{...defaults.settings,...d.settings,reminders:{...defaults.settings.reminders,...(d.settings?.reminders||{})}},transactions:d.transactions.map(x=>({...x})),tasks:d.tasks.map(x=>({...x,history:Array.isArray(x.history)?x.history:[]})),loans:d.loans.map(x=>({...x})),sheets:Array.isArray(d.sheets)?d.sheets:[]};}
function load(){try{let raw=localStorage.getItem(KEY);if(raw){state.data=validateData(JSON.parse(raw));state.loaded=true;}}catch(e){console.error('Could not load saved data',e);toast('Stored data could not be opened. Import your latest backup.');}document.documentElement.dataset.theme=localStorage.getItem(THEME)||'light';updateThemeIcon();}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state.data));state.loaded=true;window.GoalOSDrive?.changed();return true;}catch(e){toast('Unable to save in this browser. Export a backup now.');return false;}}
function all(){return state.data||blank();}function tx(){return all().transactions;}function tasks(){return all().tasks;}function loans(){return all().loans;}
function income(){return tx().filter(x=>x.type==='Credit').reduce((a,x)=>a+n(x.amount),0);}
function expenses(){return tx().filter(x=>x.type==='Debit').reduce((a,x)=>a+n(x.amount),0);}
function balance(){return n(all().settings.openingBalance)+income()-expenses();}
function balances(){let accounts=[...new Set([...(all().settings.accounts||[]),...tx().map(x=>x.account),...tx().map(x=>x.fromAccount)].filter(Boolean))];let result={};accounts.forEach(x=>result[x]=0);tx().forEach(x=>{let v=n(x.amount);if(x.type==='Credit')result[x.account]=(result[x.account]||0)+v;else if(x.type==='Debit')result[x.account]=(result[x.account]||0)-v;else if(x.type==='Money Transfer'){result[x.account]=(result[x.account]||0)+v;if(x.fromAccount)result[x.fromAccount]=(result[x.fromAccount]||0)-v;}});return result;}
function remaining(x){return Math.max(0,n(x.principal)-n(x.paid));}
function liveStatus(x){return remaining(x)<=0?'Settled':(x.status||'Pending');}
function taskDone(x){return String(x.status).toLowerCase()==='completed';}
function overdue(x){return x.dueDate && x.dueDate<today()&&!taskDone(x)&&x.status!=='Rejected';}
function clean(v){return String(v??'').trim().toLowerCase();}
function matchesSearch(row){if(!state.search)return true;return Object.values(row).map(v=>typeof v==='object'?JSON.stringify(v):String(v??'')).join(' ').toLowerCase().includes(state.search);}
function badge(value){let s=String(value??'—');let k=clean(s).replace(/[^a-z]+/g,'-');let color=/complete|settled|credit|received/.test(k)?'green':/progress|medium|transfer/.test(k)?'blue':/hold|pending|high/.test(k)?'amber':/reject|overdue|debit/.test(k)?'red':'purple';return `<span class="badge-soft badge-${color}">${safe(s)}</span>`;}
function header(eyebrow,title,desc,buttons=''){return `<div class="page-head"><div><div class="eyebrow">${safe(eyebrow)}</div><h1 class="page-title">${safe(title)}</h1><p class="page-subtitle">${safe(desc)}</p></div>${buttons?`<div class="page-head-actions">${buttons}</div>`:''}</div>`;}
function button(label,action,klass='btn-primary',other=''){return `<button type="button" class="btn ${klass}" data-action="${safe(action)}" ${other}>${label}</button>`;}
function panel(title,sub,content,right=''){return `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">${safe(title)}</h2><p class="panel-sub">${safe(sub)}</p></div>${right}</div>${content}</section>`;}
function metric(label,value,sub,ico,color='purple'){return `<div class="metric"><div class="metric-top"><span class="metric-label">${safe(label)}</span><span class="metric-icon ${color}">${icon(ico)}</span></div><div class="metric-value">${safe(value)}</div><div class="metric-foot">${safe(sub)}</div></div>`;}
function progress(v,max){let p=max?Math.max(0,Math.min(100,(v/max)*100)):0;return `<div class="progress-track"><div class="progress-fill" style="width:${p.toFixed(1)}%"></div></div>`;}
function empty(title,sub,action=''){return `<div class="empty-state"><div class="empty-art">✧</div><strong>${safe(title)}</strong><p>${safe(sub)}</p>${action}</div>`;}
function filteredRows(x){return x.filter(matchesSearch);}
function pageOverview(){if(!state.loaded)return welcome();const t=tasks(),done=t.filter(taskDone).length,remainingLoans=loans().reduce((a,x)=>a+remaining(x),0);const latest=[...tx()].sort((a,b)=>(b.date||'').localeCompare(a.date||''));let topCats=categorySpends().slice(0,5);let upcoming=[...t].filter(x=>!taskDone(x)&&x.status!=='Rejected').sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')).slice(0,5);let cur=Math.max(0,Math.min(100,t.length?done/t.length*100:0));return `<div class="page">${header('PERSONAL WORKSPACE','Your command center',`Your finances and goals at a glance · ${fmtDate(today())}`,button(`${icon('plus')} New transaction`,'new-transaction'))}<div class="hero"><div class="hero-content"><span class="hero-tag">✦ YOUR ${safe(all().settings.year)} PLAN</span><h2>Small steps. Big progress.</h2><p>All your goals, money, and commitments in one place. Keep moving forward.</p><div class="hero-buttons"><button class="hero-btn" data-action="navigate" data-to="tasks">See my goals ${icon('arrow')}</button><button class="hero-btn hero-btn-soft" data-action="navigate" data-to="analytics">View analytics</button></div></div><div class="hero-stat"><span class="micro">GOALS COMPLETED</span><strong>${done} / ${t.length}</strong><small>${cur.toFixed(0)}% of your goal tracker</small></div></div><div class="metric-grid">${metric('Estimated net cash',money(balance()),'Based on recorded entries','wallet','purple')}${metric('Recorded income',money(income()),`${tx().filter(x=>x.type==='Credit').length} credits`,'chart','green')}${metric('Recorded spending',money(expenses()),`${tx().filter(x=>x.type==='Debit').length} debits`,'wallet','red')}${metric('Outstanding loans',money(remainingLoans),`${loans().filter(x=>remaining(x)>0).length} unsettled loans`,'loan','amber')}</div><div class="layout-2">${panel('Cashflow by month','Recorded income vs spending in '+all().settings.year,monthlyChart(),`<button class="panel-link" data-action="navigate" data-to="analytics">Explore ${icon('arrow')}</button>`)}${panel('Goal progress',`${done} of ${t.length} marked complete`,donutProgress(done,t.length)+`<div class="section-divider"></div><div class="inline-info"><span>In progress: <strong>${t.filter(x=>x.status==='In Progress').length}</strong></span><span>Overdue: <strong>${t.filter(overdue).length}</strong></span></div>`)}</div><div class="layout-2 layout-even">${panel('Recent transactions','Your newest recorded movements',latest.length?`<div class="row-list">${latest.slice(0,5).map(x=>`<div class="mini-row"><div class="mini-row-left"><div class="icon-avatar">${icon(x.type==='Debit'?'wallet':'chart')}</div><div><div class="item-primary">${safe(x.description||x.category)}</div><div class="item-secondary">${fmtDate(x.date)} · ${safe(x.account)}</div></div></div><div class="mini-row-right"><div class="item-value ${x.type==='Credit'?'positive':x.type==='Debit'?'negative':''}">${x.type==='Credit'?'+':x.type==='Debit'?'-':'↔'} ${safe(money(x.amount))}</div><div>${badge(x.type)}</div></div></div>`).join('')}</div>`:empty('No transactions yet','Add one to see your history.'),`<button class="panel-link" data-action="navigate" data-to="transactions">All transactions ${icon('arrow')}</button>`)}${panel('Next goals','Tasks needing your attention',upcoming.length?`<div class="row-list">${upcoming.map(x=>`<div class="mini-row"><div><div class="item-primary">${safe(x.title)}</div><div class="item-secondary">${safe(x.category)} · ${fmtDate(x.dueDate)}</div></div><div>${overdue(x)?badge('Overdue'):badge(x.status)}</div></div>`).join('')}</div>`:empty('Everything complete','You have no open goals.'),`<button class="panel-link" data-action="navigate" data-to="tasks">All goals ${icon('arrow')}</button>`)}</div>${topCats.length?panel('Spending breakdown','Your biggest expense categories',barList(topCats)) : ''}</div>`;}
function welcome(){return `<div class="page">${header('WELCOME TO GOALOS','Your workspace is ready','Your personal data is not included in the public website files.') }<div class="welcome"><section class="welcome-card"><span class="hero-tag" style="color:var(--violet);background:var(--purple-light)">✦ LOCAL-FIRST · PRIVATE</span><h2>Bring your workbook to life.</h2><p>Import the <strong>goal2026_PRIVATE_data.json</strong> file supplied separately. All original entries, tasks, loans, and 11 workbook snapshots will appear in this dashboard.</p><div class="welcome-list"><div>${icon('check')} Finance dashboard, transactions and transfers</div><div>${icon('check')} Editable goals and progress history</div><div>${icon('check')} Loans, insights and workbook explorer</div><div>${icon('lock')} Private data saved on this device only</div></div><div class="settings-actions">${button(`${icon('upload')} Import my data`,'import-data')}${button('Start empty','start-empty','btn-neutral')}</div><p class="field-help">Do not upload your private JSON to a public GitHub repository.</p></section><div class="welcome-visual"><div class="welcome-inside"><div style="font-size:36px;margin-bottom:20px">✦</div><div class="mock-row"><span><span class="pill-dot"></span> Goal tracker</span><span>✓</span></div><div class="mock-row"><span><span class="pill-dot"></span> Cashflow</span><span>↗</span></div><div class="mock-row"><span><span class="pill-dot"></span> Loan overview</span><span>◈</span></div></div></div></div></div>`;}
function categorySpends(){const map=new Map();tx().filter(x=>x.type==='Debit').forEach(x=>map.set(x.category||'Other',(map.get(x.category||'Other')||0)+n(x.amount)));return [...map].map(([label,value])=>({label,value})).sort((a,b)=>b.value-a.value);}
function barList(data){let m=Math.max(1,...data.map(x=>x.value));return data.map((x,i)=>`<div class="simple-hbar"><span class="hbar-label" title="${safe(x.label)}">${safe(x.label)}</span><div class="hbar-track"><div class="hbar-fill" style="width:${(100*x.value/m).toFixed(2)}%;background:${['#6a5be8','#26b38a','#5b93ec','#e5a540','#ed7585','#998af6'][i%6]}"></div></div><b class="hbar-val">${safe(money(x.value))}</b></div>`).join('');}
function monthlyData(year=Number(all().settings.year)||2026){return Array.from({length:12},(_,i)=>{let k=`${year}-${String(i+1).padStart(2,'0')}`;let a=tx().filter(x=>String(x.date||'').slice(0,7)===k);return {label:new Date(year,i,1).toLocaleString('en',{month:'short'}),credit:a.filter(x=>x.type==='Credit').reduce((s,x)=>s+n(x.amount),0),debit:a.filter(x=>x.type==='Debit').reduce((s,x)=>s+n(x.amount),0)};});}
function monthlyChart(){let d=monthlyData(),max=Math.max(1,...d.flatMap(x=>[x.credit,x.debit]));const w=670,h=225,pad=29,dy=171;let ticks=[0,.25,.5,.75,1].map(q=>`<line x1="37" x2="665" y1="${(12+dy*(1-q)).toFixed(1)}" y2="${(12+dy*(1-q)).toFixed(1)}" stroke="var(--line)" stroke-dasharray="4 5"/><text x="29" y="${(16+dy*(1-q)).toFixed(1)}" font-size="9" text-anchor="end" fill="var(--muted)">${q===0?'0':Math.round(max*q).toLocaleString('en-PK')}</text>`).join('');let bars=d.map((x,i)=>{let x1=57+i*50.8;let bh=x.credit/max*dy,dh=x.debit/max*dy;return `<rect x="${x1.toFixed(1)}" y="${(12+dy-bh).toFixed(1)}" width="15" height="${Math.max(0,bh).toFixed(1)}" rx="4" fill="#6a5be8"><title>${safe(x.label)} income: ${safe(money(x.credit))}</title></rect><rect x="${(x1+19).toFixed(1)}" y="${(12+dy-dh).toFixed(1)}" width="15" height="${Math.max(0,dh).toFixed(1)}" rx="4" fill="#2db992"><title>${safe(x.label)} expenses: ${safe(money(x.debit))}</title></rect><text x="${(x1+17).toFixed(1)}" y="208" font-size="10" text-anchor="middle" fill="var(--muted)">${safe(x.label)}</text>`;}).join('');return `<div class="chart-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Grouped monthly income and spending chart">${ticks}${bars}</svg></div><div class="chart-legend"><span><i style="background:#6a5be8"></i> Income</span><span><i style="background:#2db992"></i> Spending</span></div>`;}
function donutProgress(done,total){let p=total?done/total*100:0;return `<div class="donut-layout"><div class="donut" style="background:conic-gradient(var(--violet) ${p}%,var(--purple-light) ${p}% 100%)"><div class="donut-hole"><b>${p.toFixed(0)}%</b><span>COMPLETED</span></div></div><div class="legend-list"><div class="legend-row"><i class="legend-dot" style="background:var(--violet)"></i><span>Completed</span><b>${done}</b></div><div class="legend-row"><i class="legend-dot" style="background:var(--blue)"></i><span>In progress</span><b>${tasks().filter(x=>x.status==='In Progress').length}</b></div><div class="legend-row"><i class="legend-dot" style="background:var(--amber)"></i><span>On hold</span><b>${tasks().filter(x=>x.status==='On Hold').length}</b></div><div class="legend-row"><i class="legend-dot" style="background:var(--red)"></i><span>Other</span><b>${Math.max(0,total-done-tasks().filter(x=>x.status==='In Progress'||x.status==='On Hold').length)}</b></div></div></div>`;}
function filterSelect(id,options,selected){return `<select class="select" id="${safe(id)}" data-filter="${safe(id)}" aria-label="Filter ${safe(id)}">${options.map(o=>`<option value="${safe(o)}" ${o===selected?'selected':''}>${safe(o)}</option>`).join('')}</select>`;}
function pageTransactions(){let x=filteredRows(tx()).filter(t=>state.filters.type==='All'||t.type===state.filters.type).filter(t=>state.filters.account==='All'||t.account===state.filters.account||t.fromAccount===state.filters.account).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||String(b.id).localeCompare(String(a.id)));let types=['All','Credit','Debit','Money Transfer'];const accs=['All',...[...new Set([...all().settings.accounts,...tx().map(t=>t.account),...tx().map(t=>t.fromAccount)].filter(Boolean))]];return `<div class="page">${header('MONEY MANAGEMENT','Transactions',`${tx().length} recorded entries · credit, debit and account transfers`,button(`${icon('plus')} Add transaction`,'new-transaction')+button(`${icon('download')} Export CSV`,'export-transactions','btn-neutral'))}<div class="metric-grid">${metric('Total credited',money(income()),'Excludes transfers','chart','green')}${metric('Total debited',money(expenses()),'Excludes transfers','wallet','red')}${metric('Net cash change',money(income()-expenses()),'Without opening balances','chart','purple')}${metric('Transfers recorded',String(tx().filter(t=>t.type==='Money Transfer').length),'Between accounts','wallet','blue')}</div>${panel('Transaction ledger',`Showing ${x.length} of ${tx().length} records`, `<div class="filters"><div class="filter-right">${filterSelect('type',types,state.filters.type)}${filterSelect('account',accs,state.filters.account)}</div></div>${x.length?`<div class="table-scroller"><table class="data-table"><thead><tr><th>Date</th><th>Details</th><th>Type</th><th>Category</th><th>Account</th><th class="td-right">Amount</th><th>Actions</th></tr></thead><tbody>${x.map(t=>`<tr><td>${fmtDate(t.date)}</td><td><div class="table-main">${safe(t.description||'—')}</div><div class="table-muted">${safe(t.id)}${t.notes?` · ${safe(t.notes.slice(0,55))}`:''}</div></td><td>${badge(t.type)}</td><td>${safe(t.category)}</td><td>${safe(t.account||'—')}${t.type==='Money Transfer'?`<div class="table-muted">from ${safe(t.fromAccount||'Unknown')}</div>`:''}</td><td class="td-right font-bold ${t.type==='Credit'?'positive':t.type==='Debit'?'negative':''}">${t.type==='Credit'?'+':t.type==='Debit'?'-':'↔'} ${safe(money(t.amount))}</td><td><div class="tiny-actions"><button data-action="view-transaction" data-id="${safe(t.id)}" title="View details">${icon('search')}</button><button data-action="edit-transaction" data-id="${safe(t.id)}" title="Edit">${icon('edit')}</button><button data-action="delete-transaction" data-id="${safe(t.id)}" title="Delete">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('No matching records','Try changing your filters or add a transaction.')}`)}${panel('Account movements','Calculated using recorded transactions; opening account allocations were not in the source workbook',`<div class="row-list">${Object.entries(balances()).map(([name,value])=>`<div class="mini-row"><div class="item-primary">${safe(name)}</div><div class="item-value ${value<0?'negative':''}">${safe(money(value))}</div></div>`).join('')}</div><p class="field-help">These are recorded movements, not verified bank balances. Transfers move money between accounts without changing total income or spending.</p>`)}</div>`;}
function pageTasks(){let x=filteredRows(tasks()).filter(t=>state.filters.status==='All'||t.status===state.filters.status).filter(t=>state.filters.priority==='All'||t.priority===state.filters.priority);if(state.filters.taskSort==='due')x.sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));else if(state.filters.taskSort==='priority')x.sort((a,b)=>({High:0,Medium:1,Low:2}[a.priority]??3)-({High:0,Medium:1,Low:2}[b.priority]??3));else if(state.filters.taskSort==='title')x.sort((a,b)=>a.title.localeCompare(b.title));let done=tasks().filter(taskDone).length;return `<div class="page">${header('GOALS & ACTIONS','Goal tracker',`${tasks().length} goals imported · all task notes and progress entries preserved`,button(`${icon('plus')} Add goal`,'new-task')+button(`${icon('download')} Export CSV`,'export-tasks','btn-neutral'))}<div class="metric-grid">${metric('All goals',String(tasks().length),'Across every category','check','purple')}${metric('Completed',String(done),`${tasks().length?Math.round(done/tasks().length*100):0}% completion`,'check','green')}${metric('In progress',String(tasks().filter(x=>x.status==='In Progress').length),'Actively being worked on','chart','blue')}${metric('Overdue',String(tasks().filter(overdue).length),'Open and past due','alert','red')}</div>${panel('Your progress','Completion rate across all goals',`${progress(done,tasks().length)}<div class="progress-info"><span>${done} done</span><span>${tasks().length-done} not completed</span></div>`)}<div class="filters"><div class="filter-right">${filterSelect('status',['All','Not Started','In Progress','On Hold','Completed','Rejected'],state.filters.status)}${filterSelect('priority',['All','High','Medium','Low'],state.filters.priority)}${filterSelect('taskSort',['due','priority','title'],state.filters.taskSort)}</div></div>${x.length?`<div class="task-grid">${x.map(t=>`<article class="task-card"><div class="task-card-top"><span>${badge(t.category)}</span>${badge(t.priority)}</div><h2 class="task-title">${safe(t.title)}</h2><p class="task-note">${safe(t.remarks||t.blocker||'No notes added')}</p><div class="inline-info"><span>Status: ${badge(t.status)}</span>${overdue(t)?badge('Overdue'):''}</div>${t.blocker&&t.blocker!=='None'?`<div class="task-history">Blocker: ${safe(t.blocker)}</div>`:''}<div class="task-card-footer"><div class="task-date">${icon('calendar')} ${fmtDate(t.dueDate)}</div><div class="tiny-actions"><button data-action="view-task" data-id="${safe(t.id)}" title="View details & history">${icon('book')}</button><button data-action="edit-task" data-id="${safe(t.id)}" title="Edit">${icon('edit')}</button><button data-action="delete-task" data-id="${safe(t.id)}" title="Delete">${icon('trash')}</button></div></div><div class="settings-actions"><button class="btn btn-small ${taskDone(t)?'btn-neutral':'btn-secondary'}" data-action="toggle-task" data-id="${safe(t.id)}">${taskDone(t)?'Reopen goal':'Mark completed'}</button></div></article>`).join('')}</div>`:empty('No goals match','Change the filters or add a new goal.')}</div>`;}
function pageLoans(){let x=filteredRows(loans());let out=loans().reduce((a,t)=>a+remaining(t),0),principal=loans().reduce((a,t)=>a+n(t.principal),0),paid=loans().reduce((a,t)=>a+Math.min(n(t.principal),n(t.paid)),0);return `<div class="page">${header('PERSONAL LIABILITIES','Loan tracker','Track people, amounts, payments, due dates and remaining balances',button(`${icon('plus')} Add loan`,'new-loan')+button(`${icon('download')} Export CSV`,'export-loans','btn-neutral'))}<div class="metric-grid">${metric('Total principal',money(principal),`${loans().length} loans`,'loan','purple')}${metric('Amount repaid',money(paid),'Recorded payments','check','green')}${metric('Still outstanding',money(out),'Unsettled balances','wallet','red')}${metric('Settled loans',`${loans().filter(x=>remaining(x)<=0).length} / ${loans().length}`,'Fully paid','check','blue')}</div>${x.length?`<div class="loan-grid">${x.map(l=>{let rem=remaining(l),pct=n(l.principal)?Math.min(100,100*n(l.paid)/n(l.principal)):100;return `<article class="loan-card"><div class="task-card-top">${badge(l.type)} ${badge(liveStatus(l))}</div><h2 class="loan-person">${safe(l.person)}</h2><div class="loan-kicker">${safe(l.id)} · Opened ${fmtDate(l.issueDate)}</div><div class="loan-amount">${safe(money(rem))}</div><div class="loan-kicker">remaining of ${safe(money(l.principal))}</div><div class="mt16">${progress(l.paid,l.principal)}<div class="progress-info"><span>${pct.toFixed(0)}% repaid</span><span>${safe(money(l.paid))}</span></div></div><div class="loan-bottom"><div class="task-date">${icon('calendar')} ${l.dueDate?fmtDate(l.dueDate):'No due date'}</div><div class="tiny-actions"><button data-action="view-loan" data-id="${safe(l.id)}" title="Details">${icon('book')}</button><button data-action="edit-loan" data-id="${safe(l.id)}" title="Edit loan">${icon('edit')}</button><button data-action="delete-loan" data-id="${safe(l.id)}" title="Delete loan">${icon('trash')}</button></div></div>${rem>0?`<div class="settings-actions"><button class="btn btn-small btn-secondary" data-action="loan-payment" data-id="${safe(l.id)}">Record payment</button></div>`:''}</article>`;}).join('')}</div>`:empty('No loans yet','Add a loan to start tracking payments.',button('Add loan','new-loan'))}<div class="notice mt20"><strong>Accounting note:</strong> Loan records are tracked separately from the transaction ledger. Recording a loan payment here does not automatically create a cash transaction; record the cash movement separately when needed.</div></div>`;}
function pageAnalytics(){let d=monthlyData(),sp=categorySpends(),byType=Object.entries(balances()).map(([label,value])=>({label,value:Math.abs(value)})),total=income()+expenses();let monthly=tx().reduce((a,t)=>{let m=String(t.date||'').slice(0,7);if(!m)return a;(a[m]??={credit:0,debit:0});if(t.type==='Credit')a[m].credit+=n(t.amount);if(t.type==='Debit')a[m].debit+=n(t.amount);return a;},{});return `<div class="page">${header('INSIGHTS & REPORTS','Analytics','Every chart is calculated from your saved entries — not hardcoded spreadsheet totals',button(`${icon('download')} Export transactions`,'export-transactions','btn-neutral'))}<div class="metric-grid">${metric('Cash inflow',money(income()),'Credits recorded','chart','green')}${metric('Cash outflow',money(expenses()),'Debits recorded','wallet','red')}${metric('Net recorded',money(income()-expenses()),'Credits less debits','chart','purple')}${metric('Expense categories',String(sp.length),'Categories with spending','filter','blue')}</div>${panel('Monthly cashflow',`Income and spending for ${all().settings.year}`,monthlyChart())}<div class="layout-2 layout-even">${panel('Spending by category','Highest to lowest',sp.length?barList(sp):empty('No expenses','Add debit transactions to see spending patterns.'))}${panel('Financial summary','Reconciled from the recorded transaction list',`<div class="row-list"><div class="mini-row"><div class="item-primary">Opening balance (total)</div><div class="item-value">${safe(money(all().settings.openingBalance))}</div></div><div class="mini-row"><div class="item-primary">Income / Credits</div><div class="item-value positive">+ ${safe(money(income()))}</div></div><div class="mini-row"><div class="item-primary">Spending / Debits</div><div class="item-value negative">− ${safe(money(expenses()))}</div></div><div class="mini-row"><div class="item-primary">Internal transfers</div><div class="item-value">${safe(money(tx().filter(t=>t.type==='Money Transfer').reduce((s,t)=>s+n(t.amount),0)))}</div></div><div class="mini-row"><div class="item-primary">Estimated net cash</div><div class="item-value">${safe(money(balance()))}</div></div></div><p class="field-help mt16">Transfers are excluded from total net cash. Account balances may require opening account allocations to match actual bank balances.</p>`)}</div><div class="layout-2 layout-even">${panel('Account movements','Based on available entries',Object.entries(balances()).length?`<div class="row-list">${Object.entries(balances()).map(([label,value])=>`<div class="mini-row"><div class="item-primary">${safe(label)}</div><div class="item-value ${value<0?'negative':''}">${safe(money(value))}</div></div>`).join('')}</div>`:empty('No accounts','Add accounts in Settings.'))}${panel('Goal status distribution','Current live statuses',`<div class="row-list">${[...new Set(tasks().map(t=>t.status))].map(s=>`<div class="mini-row"><div class="item-primary">${badge(s)}</div><div class="item-value">${tasks().filter(t=>t.status===s).length}</div></div>`).join('')}</div>`)} </div>${panel('Monthly activity log','All months with posted income or expenses',Object.keys(monthly).length?`<div class="table-scroller"><table class="data-table"><thead><tr><th>Month</th><th class="td-right">Income</th><th class="td-right">Expenses</th><th class="td-right">Net</th></tr></thead><tbody>${Object.entries(monthly).sort((a,b)=>b[0].localeCompare(a[0])).map(([k,v])=>`<tr><td>${safe(k)}</td><td class="td-right positive">${safe(money(v.credit))}</td><td class="td-right negative">${safe(money(v.debit))}</td><td class="td-right">${safe(money(v.credit-v.debit))}</td></tr>`).join('')}</tbody></table></div>`:empty('No monthly activity','Transactions will appear here.'))}</div>`;}
function colLetter(c){let s='';for(let i=c+1;i;i=Math.floor((i-1)/26))s=String.fromCharCode(65+(i-1)%26)+s;return s;}
function pageWorkbook(){let sheets=all().sheets||[];if(!sheets.length)return `<div class="page">${header('ORIGINAL SPREADSHEET','Workbook explorer','Browse an imported snapshot of the original Excel sheets')}${empty('No workbook snapshots','Import your private JSON conversion to view the original Excel sheet values.',button('Import file','import-data'))}</div>`;state.sheet=Math.max(0,Math.min(state.sheet,sheets.length-1));let sheet=sheets[state.sheet],rows=sheet.rows||[],count=Math.min(Number(sheet.columns)||0,28),needle=state.search;let visible=rows.filter(r=>!needle||JSON.stringify(r.cells).toLowerCase().includes(needle)||String(r.row).includes(needle));return `<div class="page">${header('ORIGINAL SPREADSHEET','Workbook explorer',`${sheets.length} original workbook sheets · imported snapshot (read-only)`,button(`${icon('download')} Export backup`,'export-backup','btn-neutral'))}<div class="notice private mb20"><strong>Original workbook archive:</strong> These are the sheet values captured when the Excel file was converted. Edits in the live trackers do not change this historic snapshot. Export a backup to save both the live trackers and archive.</div><div class="panel"><div class="sheet-buttons">${sheets.map((s,i)=>`<button class="btn btn-small ${state.sheet===i?'btn-primary':'btn-neutral'}" data-action="switch-sheet" data-index="${i}">${safe(s.name)}</button>`).join('')}</div><div class="panel-head"><div><h2 class="panel-title">${safe(sheet.name)}</h2><p class="panel-sub">${visible.length} of ${rows.length} populated rows · ${count} columns</p></div></div>${visible.length?`<div class="sheet-scroll"><table class="sheet-table"><thead><tr><th class="rownum">#</th>${Array.from({length:count},(_,i)=>`<th>${colLetter(i)}</th>`).join('')}</tr></thead><tbody>${visible.map(r=>`<tr><td class="rownum">${r.row}</td>${Array.from({length:count},(_,i)=>`<td>${safe(r.cells?.[i]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('No matching cells','Try another search term.')}</div></div>`;}
function pageSettings(){let s=all().settings;return `<div class="page">${header('YOUR WORKSPACE','Settings & backup','Customize preferences, import the original workbook conversion and protect your information')}<div class="settings-grid">${panel('Workspace preferences','Saved locally in this browser',`<form id="settingsForm" class="setting-group"><div class="form-row"><div class="form-field"><label for="setYear">Planning year</label><input id="setYear" name="year" type="number" min="2000" max="2100" value="${safe(s.year)}" required></div><div class="form-field"><label for="setCurrency">Currency label</label><input id="setCurrency" name="currency" value="${safe(s.currency)}" maxlength="8" required></div></div><div class="form-row"><div class="form-field"><label for="setOpening">Opening cash balance (all accounts)</label><input id="setOpening" name="openingBalance" type="number" step="0.01" value="${safe(s.openingBalance)}" required></div><div class="form-field"><label for="setSavings">Monthly savings goal</label><input id="setSavings" name="savingsTarget" type="number" min="0" step="0.01" value="${safe(s.savingsTarget)}" required></div></div><div class="form-field"><label for="setAccounts">Accounts (one per line)</label><textarea id="setAccounts" name="accounts">${safe((s.accounts||[]).join('\n'))}</textarea></div><div class="form-field"><label for="setCategories">Transaction categories (one per line)</label><textarea id="setCategories" name="categories">${safe((s.categories||[]).join('\n'))}</textarea></div><button class="btn btn-primary" type="submit">Save preferences</button></form>`)}${panel('Private data & backup','Your records do not live in GitHub',`<div class="notice private"><strong>${state.loaded?'Data is loaded':'No private data imported yet'}.</strong> Data is saved locally first. Drive syncing is optional and only begins after you connect and back up.</div><div class="settings-actions">${button(`${icon('upload')} Import JSON`,'import-data')}${button(`${icon('download')} Export JSON`,'export-backup','btn-neutral')}</div><div class="section-divider"></div><p class="field-help">Backup often. Browser storage can be lost when you clear site data, switch devices, or use private browsing.</p><div class="notice unsafe"><strong>Privacy warning:</strong> Do not commit <code>goal2026_PRIVATE_data.json</code>, your backup files, or the source Excel workbook to a public repository. Anyone can read public GitHub files.</div><div class="section-divider"></div><div class="settings-actions">${button('Clear data on this browser','clear-data','btn-danger')}${button('Start a new empty workspace','start-empty','btn-neutral')}</div>`)}</div>${panel('Google Drive cloud backup','Private Google Drive file + automatic sync while connected',window.GoalOSDrive?.html()||'Drive integration did not load.')}${panel('Gmail deadline reminders','Automatically email yourself using your personal Apps Script scheduler',`<div class="notice private"><strong>Runs even when GoalOS is closed.</strong> Install your own private Google Apps Script daily trigger (once) so Gmail reminders and daily Drive snapshots continue without the website open. The script reads your last successfully synced Drive data; unsynced browser changes cannot be included.</div><form id="remindersForm" class="setting-group"><label class="check-row"><input type="checkbox" name="remindersEnabled" ${s.reminders?.enabled!==false?'checked':''}> Enable deadline reminder emails</label><div class="form-field"><label for="reminderDays">Send reminders on these days before deadline</label><input id="reminderDays" name="reminderDays" value="${safe((s.reminders?.daysBefore||[7,3,1,0]).join(','))}" maxlength="60" required><p class="field-help">Example: 7,3,1,0 means 7, 3, 1 days before and on the due date. Use -1 for one day overdue. Already completed and rejected goals are skipped.</p></div><button type="submit" class="btn btn-primary">Save reminder preferences</button></form><div class="section-divider"></div><div class="settings-actions"><a class="btn btn-neutral" href="https://script.google.com/home/projects/create" target="_blank" rel="noopener noreferrer">Set up Gmail automation ↗</a><a class="btn btn-neutral" href="SETUP_GOOGLE.md" target="_blank" rel="noopener noreferrer">Full setup guide ↗</a></div><p class="field-help"><strong>Gmail connection:</strong> Open <a href="https://script.google.com/home/projects/create" target="_blank" rel="noopener noreferrer">Google Apps Script ↗</a>, paste the supplied <code>google-apps-script/Code.gs</code>, set your email address, then run <code>installDailyTrigger</code> and <code>sendTestEmail</code> to authorize emails. See <a href="SETUP_GOOGLE.md" target="_blank">step-by-step setup guide ↗</a>.</p>`) }${panel('Data summary','What is currently loaded',`<div class="inline-info"><span><strong>${tx().length}</strong> transactions</span><span><strong>${tasks().length}</strong> goals</span><span><strong>${loans().length}</strong> loans</span><span><strong>${(all().sheets||[]).length}</strong> archived sheets</span></div><p class="field-help mt16">Source: ${safe(all().meta?.sourceFile||'—')} · Imported: ${safe(all().meta?.importedAt||'—')}</p>`)}</div>`;}
function render(){if(!app)return;app.innerHTML=({overview:pageOverview,transactions:pageTransactions,tasks:pageTasks,loans:pageLoans,analytics:pageAnalytics,workbook:pageWorkbook,settings:pageSettings}[state.page]||pageOverview)();el('breadcrumb').textContent=PAGES[state.page];document.querySelectorAll('.nav-item').forEach(b=>{let active=b.dataset.page===state.page;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});if(el('globalSearch')){el('globalSearch').value=state.search;el('globalSearch').placeholder=state.page==='workbook'?'Search sheet cells...':'Search this page...';}if(!state.loaded&&state.page!=='overview'&&state.page!=='settings'&&state.page!=='workbook'){/* allow empty views */}}
function navigate(page){if(!PAGES[page])return;state.page=page;state.search='';state.filters={type:'All',status:'All',priority:'All',taskSort:'due',account:'All',period:'All'};el('sidebar').classList.remove('open');el('sidebarOverlay').classList.remove('show');render();window.scrollTo({top:0,behavior:'smooth'});}
function toast(msg){let stack=el('toastStack');if(!stack)return;let div=document.createElement('div');div.className='toast';div.textContent=msg;stack.appendChild(div);setTimeout(()=>div.remove(),3600);}
function modal(title,desc,content,onsubmit){let backdrop=el('modalBackdrop'),root=el('modalContent');root.innerHTML=`<div class="modal-top"><div><h2 class="modal-title">${safe(title)}</h2><p class="modal-desc">${safe(desc)}</p></div><button class="icon-button" type="button" data-action="close-modal" aria-label="Close">${icon('close')}</button></div>${onsubmit?`<form class="modal-form" id="modalForm">${content}<div class="modal-bottom"><button type="button" class="btn btn-neutral" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">Save changes</button></div></form>`:content}`;backdrop.classList.add('show');backdrop.setAttribute('aria-hidden','false');backdrop._submit=onsubmit;setTimeout(()=>root.querySelector('input:not([type=hidden]),select,textarea,button')?.focus(),0);}
function closeModal(){el('modalBackdrop').classList.remove('show');el('modalBackdrop').setAttribute('aria-hidden','true');el('modalBackdrop')._submit=null;}
function field(label,name,val='',type='text',more=''){return `<div class="form-field"><label for="f-${safe(name)}">${safe(label)}</label>${type==='textarea'?`<textarea id="f-${safe(name)}" name="${safe(name)}" ${more}>${safe(val)}</textarea>`:`<input id="f-${safe(name)}" name="${safe(name)}" type="${type}" value="${safe(val)}" ${more}>`}</div>`;}
function options(label,name,opts,val){return `<div class="form-field"><label for="f-${safe(name)}">${safe(label)}</label><select id="f-${safe(name)}" name="${safe(name)}">${opts.map(o=>`<option ${String(val)===String(o)?'selected':''} value="${safe(o)}">${safe(o)}</option>`).join('')}</select></div>`;}
function formVals(form){return Object.fromEntries(new FormData(form).entries());}
function nextId(prefix,items){let n=Math.max(100,...items.map(x=>Number(String(x.id||'').match(/(\d+)$/)?.[1])||0));let id;do{id=`${prefix}-${++n}`;}while(items.some(x=>x.id===id));return id;}
function editTransaction(id){if(!state.data){state.data=blank();persist();}let existing=tx().find(x=>x.id===id),t=existing||{date:today(),type:'Debit',category:'Food',account:all().settings.accounts?.[0]||'Cash',fromAccount:'',amount:'',description:'',notes:''};let accounts=[...new Set([...(all().settings.accounts||[]),t.account,t.fromAccount].filter(Boolean))];let categories=[...new Set([...(all().settings.categories||[]),t.category].filter(Boolean))];let f=`<div class="form-row">${field('Date','date',t.date,'date','required')}${options('Type','type',['Debit','Credit','Money Transfer'],t.type)}</div><div class="form-row">${options('Category','category',categories,t.category)}${field('Amount','amount',t.amount,'number','min="0.01" step="0.01" required')}</div>${field('Description','description',t.description,'text','maxlength="250" required')}<div class="form-row">${options('Account receiving / paying','account',accounts,t.account)}${options('From account (transfers)','fromAccount',['',...accounts],t.fromAccount)}</div>${field('Notes / details','notes',t.notes||'','textarea')}`;modal(existing?'Edit transaction':'New transaction','For a transfer, choose both the destination and source accounts.',f,values=>{let x={...t,...values,amount:Number(values.amount),notes:values.notes.trim()};if(!x.date||!x.description.trim()||!(x.amount>0))throw Error('Enter a date, description and amount greater than zero.');if(x.type==='Money Transfer'){if(!x.fromAccount||x.fromAccount===x.account)throw Error('Select a different source and destination account for transfers.');x.category=`Transfer from ${x.fromAccount}`;}else x.fromAccount='';if(existing)Object.assign(existing,x);else tx().push({...x,id:nextId('TXN',tx())});persist();render();toast(existing?'Transaction updated':'Transaction added');});}
function editTask(id){if(!state.data){state.data=blank();persist();}let existing=tasks().find(x=>x.id===id),t=existing||{title:'',category:'Career',priority:'Medium',dueDate:'',status:'Not Started',blocker:'',remarks:'',history:[]};let f=`${field('Goal / task name','title',t.title,'text','required maxlength="250"')}<div class="form-row">${field('Category','category',t.category,'text','required')}${options('Priority','priority',['High','Medium','Low'],t.priority)}</div><div class="form-row">${field('Due date','dueDate',t.dueDate,'date')}${options('Status','status',['Not Started','In Progress','On Hold','Completed','Rejected'],t.status)}</div>${field('Blocker / dependency','blocker',t.blocker,'textarea')}${field('Remarks and next steps','remarks',t.remarks,'textarea')}${field('New progress update (optional)','newUpdate','','textarea')}`;modal(existing?'Edit goal':'Add new goal','Changing status and adding notes helps you track progress over time.',f,values=>{let update=values.newUpdate?.trim(),x={...values,title:values.title.trim(),category:values.category.trim(),history:t.history||[]};delete x.newUpdate;if(!x.title)throw Error('Enter a goal title.');if(update)x.history=[...x.history,{date:today(),note:update}];if(existing)Object.assign(existing,x);else tasks().push({...x,id:nextId('TSK',tasks())});persist();render();toast(existing?'Goal updated':'Goal added');});}
function editLoan(id){if(!state.data){state.data=blank();persist();}let existing=loans().find(x=>x.id===id),t=existing||{person:'',type:'Loan to Pay',issueDate:today(),dueDate:'',principal:'',paid:0,status:'Pending'};let f=`${field('Person or organization','person',t.person,'text','required maxlength="250"')}<div class="form-row">${options('Loan direction','type',['Loan to Pay','Loan to Receive'],t.type)}${options('Status','status',['Pending','Partial','Settled','Overdue'],t.status)}</div><div class="form-row">${field('Issued date','issueDate',t.issueDate,'date')}${field('Due date (optional)','dueDate',t.dueDate,'date')}</div><div class="form-row">${field('Original amount','principal',t.principal,'number','min="0.01" step="0.01" required')}${field('Amount already paid','paid',t.paid,'number','min="0" step="0.01" required')}</div>`;modal(existing?'Edit loan':'Add loan','Keep amounts and payment history up to date.',f,values=>{let x={...values,principal:Number(values.principal),paid:Number(values.paid),person:values.person.trim()};if(!x.person||!(x.principal>0)||x.paid<0||x.paid>x.principal)throw Error('Check the name and payment amounts. Paid cannot exceed principal.');if(x.paid>=x.principal)x.status='Settled';else if(x.paid>0&&x.status==='Settled')x.status='Partial';if(existing)Object.assign(existing,x);else loans().push({...x,id:nextId('LOAN',loans())});persist();render();toast(existing?'Loan updated':'Loan added');});}
function payLoan(id){let l=loans().find(x=>x.id===id);if(!l)return;modal('Record a loan payment',`Remaining: ${money(remaining(l))}`,field('Payment amount','amount','','number',`min="0.01" max="${remaining(l)}" step="0.01" required`),v=>{let amount=Number(v.amount);if(!(amount>0)||amount>remaining(l))throw Error('Payment must be greater than zero and no more than the remaining balance.');l.paid=n(l.paid)+amount;l.status=remaining(l)<=0?'Settled':'Partial';persist();render();toast('Payment recorded');});}
function details(type,id){let x=({transaction:tx(),task:tasks(),loan:loans()}[type]||[]).find(x=>x.id===id);if(!x)return;let values=Object.entries(x).filter(([k])=>k!=='history').map(([k,v])=>`<div class="mini-row"><div class="item-secondary">${safe(k.replace(/([A-Z])/g,' $1').replace(/^./,m=>m.toUpperCase()))}</div><div class="item-value" style="max-width:65%;white-space:normal;overflow-wrap:anywhere">${safe(v===null?'':v)}</div></div>`).join('');let history=type==='task'&&x.history?.length?`<div class="section-divider"></div><h3>Progress history (${x.history.length})</h3>${x.history.map(h=>`<div class="mini-row"><div class="item-secondary">${safe(h.date||'')}</div><div style="max-width:70%;overflow-wrap:anywhere">${safe(h.note)}</div></div>`).join('')}`:'';modal(`${type[0].toUpperCase()+type.slice(1)} details`,String(x.id),`<div class="row-list">${values}${history}</div><div class="modal-bottom">${button(`${icon('edit')} Edit`,'edit-'+type,'btn-primary',`data-id="${safe(x.id)}"`)}${button('Close','close-modal','btn-neutral')}</div>`,null);}
function deleteEntry(type,id){let map={transaction:'transactions',task:'tasks',loan:'loans'},prop=map[type];if(!prop)return;if(!window.confirm(`Delete this ${type}? This cannot be undone unless you have a backup.`))return;state.data[prop]=state.data[prop].filter(x=>x.id!==id);persist();render();toast(`${type} deleted`);}
function download(name,body,mime){let blob=new Blob([body],{type:mime});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),600);}
function exportBackup(){download(`goalos-private-backup-${today()}.json`,JSON.stringify(all(),null,2),'application/json;charset=utf-8');toast('Private JSON backup downloaded');}
function csvEscape(x){let s=String(x??'');return /[",\n\r]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}
function exportCSV(kind){let lists={transactions:tx(),tasks:tasks(),loans:loans()},items=lists[kind]||[];let keys={transactions:['id','date','type','category','description','account','fromAccount','amount','notes'],tasks:['id','title','category','priority','dueDate','status','blocker','remarks','history'],loans:['id','person','type','issueDate','dueDate','principal','paid','status']}[kind];let rows=[keys.join(','),...items.map(item=>keys.map(k=>csvEscape(typeof item[k]==='object'?JSON.stringify(item[k]):item[k])).join(','))].join('\r\n');download(`goalos-${kind}-${today()}.csv`,'\ufeff'+rows,'text/csv;charset=utf-8');toast('CSV downloaded');}
async function importFile(file){if(!file)return;try{if(file.size>15*1024*1024)throw Error('File is too large (15 MB maximum).');let x=validateData(JSON.parse(await file.text()));if(state.loaded&&!window.confirm('Replace all current goals, transactions and loans with this imported backup? Export a backup first if you want to keep your current changes.'))return;state.data=x;state.loaded=true;state.sheet=0;persist();navigate('overview');toast(`Imported ${x.transactions.length} transactions, ${x.tasks.length} goals and ${x.loans.length} loans.`);}catch(e){toast(e.message||'Could not import the JSON.');}finally{el('privateImport').value='';}}
function updateThemeIcon(){let use=el('themeToggle')?.querySelector('use');if(use)use.setAttribute('href',document.documentElement.dataset.theme==='dark'?'#i-sun':'#i-moon');}
function action(e){const target=e.target.closest('[data-action]');if(!target)return;let a=target.dataset.action,id=target.dataset.id;switch(a){case 'navigate':navigate(target.dataset.to);break;case 'new-transaction':editTransaction();break;case 'edit-transaction':editTransaction(id);break;case 'view-transaction':details('transaction',id);break;case 'delete-transaction':deleteEntry('transaction',id);break;case 'new-task':editTask();break;case 'edit-task':editTask(id);break;case 'view-task':details('task',id);break;case 'delete-task':deleteEntry('task',id);break;case 'toggle-task':{let x=tasks().find(t=>t.id===id);if(x){x.status=taskDone(x)?'In Progress':'Completed';x.history??=[];x.history.push({date:today(),note:`Status changed to ${x.status}`});persist();render();toast('Goal status updated');}break;}case 'new-loan':editLoan();break;case 'edit-loan':editLoan(id);break;case 'view-loan':details('loan',id);break;case 'delete-loan':deleteEntry('loan',id);break;case 'loan-payment':payLoan(id);break;case 'import-data':el('privateImport').click();break;case 'connect-drive':case 'disconnect-drive':case 'sync-drive':case 'restore-drive':window.GoalOSDrive?.handle(a);break;case 'export-backup':exportBackup();break;case 'export-transactions':exportCSV('transactions');break;case 'export-tasks':exportCSV('tasks');break;case 'export-loans':exportCSV('loans');break;case 'close-modal':closeModal();break;case 'switch-sheet':state.sheet=Number(target.dataset.index)||0;render();break;case 'clear-data':if(window.confirm('Permanently remove ALL workspace records from THIS browser? Export a backup first.')){localStorage.removeItem(KEY);state.data=null;state.loaded=false;state.search='';navigate('overview');toast('Browser data cleared');}break;case 'start-empty':if(state.loaded&&!window.confirm('Replace all current records with an empty workspace?'))return;state.data=blank();persist();navigate('overview');toast('New empty workspace created');break;}}
function init(){load();window.GoalOSDrive?.init({getData:()=>state.data,toast,renderSettings:()=>{if(state.page==='settings')render();},restoreData:incoming=>{state.data=validateData(incoming);state.loaded=true;persist();navigate('overview');}});app.addEventListener('click',action);el('modalBackdrop').addEventListener('click',e=>{if(e.target===el('modalBackdrop'))closeModal();else action(e);});el('navigation').addEventListener('click',e=>{let p=e.target.closest('[data-page]')?.dataset.page;if(p)navigate(p);});document.querySelectorAll('.nav-item[data-page]').forEach(b=>{if(!el('navigation').contains(b))b.addEventListener('click',()=>navigate(b.dataset.page));});el('globalSearch').addEventListener('input',e=>{state.search=e.target.value.trim().toLowerCase();render();});app.addEventListener('change',e=>{if(e.target.dataset.filter){state.filters[e.target.dataset.filter]=e.target.value;render();}});app.addEventListener('submit',e=>{if(e.target.id==='remindersForm'){e.preventDefault();let values=formVals(e.target);let list=String(values.reminderDays||'').split(',').map(x=>x.trim());if(!list.length||list.some(x=>!/^\-?\d+$/.test(x)||Number(x)<-30||Number(x)>365)){toast('Enter comma-separated numbers from -30 to 365 (for example 7,3,1,0).');return;}let days=[...new Set(list.map(Number))];if(days.length>12){toast('Choose up to 12 reminder days.');return;}if(!state.data)state.data=blank();state.data.settings.reminders={enabled:values.remindersEnabled==='on',daysBefore:days};persist();render();toast('Reminder settings saved; sync to Drive so the daily script sees the changes.');return;}if(e.target.id==='settingsForm'){e.preventDefault();let v=formVals(e.target);if(!state.data)state.data=blank();let s=state.data.settings;s.year=Number(v.year);s.currency=String(v.currency||'PKR').trim();s.openingBalance=Number(v.openingBalance)||0;s.savingsTarget=Number(v.savingsTarget)||0;s.accounts=String(v.accounts).split(/\r?\n/).map(x=>x.trim()).filter(Boolean);s.categories=String(v.categories).split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!state.data)state.data=blank();persist();render();toast('Preferences saved');}});el('modalBackdrop').addEventListener('submit',e=>{if(e.target.id!=='modalForm')return;e.preventDefault();try{let fn=el('modalBackdrop')._submit;if(fn){fn(formVals(e.target));closeModal();}}catch(err){toast(err.message||'Please check the form.');}});el('privateImport').addEventListener('change',e=>importFile(e.target.files?.[0]));el('menuToggle').addEventListener('click',()=>{el('sidebar').classList.toggle('open');el('sidebarOverlay').classList.toggle('show');});el('sidebarOverlay').addEventListener('click',()=>{el('sidebar').classList.remove('open');el('sidebarOverlay').classList.remove('show');});el('themeToggle').addEventListener('click',()=>{let theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem(THEME,theme);updateThemeIcon();});el('quickAdd').addEventListener('click',()=>{if(state.page==='tasks')editTask();else if(state.page==='loans')editLoan();else editTransaction();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});render();if('serviceWorker' in navigator && location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
